// Validar e preparar dados recebidos
const inputData = $input.item.json;

// Extrair sintomas e dados do paciente
const symptoms = inputData.symptoms || [];
const patientInfo = inputData.patientInfo || {};
const additionalNotes = inputData.additionalNotes || inputData.notes || '';

// Construir contexto para IA
const symptomsList = Array.isArray(symptoms) 
  ? symptoms.join(', ') 
  : symptoms;

const patientContext = `
Paciente: ${patientInfo.age || 'Idade não informada'} anos, ${patientInfo.gender || 'Sexo não informado'}
Histórico Médico: ${patientInfo.medicalHistory?.join(', ') || patientInfo.chronicConditions?.join(', ') || 'Não informado'}
Sintomas relatados: ${symptomsList}
Observações adicionais: ${additionalNotes}
`;

// Preparar body para GROQ
const groqBody = {
  model: "llama-3.3-70b-versatile",
  messages: [
    {
      role: "system",
      content: `Você é um médico de emergência especializado em triagem. ANALISE CUIDADOSAMENTE os sintomas fornecidos.

**EMERGÊNCIA** (Score 8-10) - AMEAÇA IMEDIATA À VIDA:
→ INFARTO DO MIOCÁRDIO: dor no peito + irradiação para braço/mandíbula + falta de ar + suor frio
→ AVC: paralisia súbita, perda de fala, perda de coordenação
→ Convulsões ativas, sangramento descontrolado, perda de consciência
→ Dispneia severa com cianose

**URGENTE** (Score 6-7):
→ Dor torácica severa sem todos os critérios de infarto
→ Trauma moderado/grave, queimaduras extensas
→ Febre > 40°C com sintomas graves

**PRIORITÁRIO** (Score 4-5):
→ Dor moderada, infecções leves
→ Sintomas crônicos agudizados

**NÃO URGENTE** (Score 1-3):
→ Sintomas leves e estáveis

RESPONDA APENAS COM JSON VÁLIDO contendo: classification (EMERGÊNCIA|URGENTE|PRIORITÁRIO|NÃO_URGENTE), severity_score (1-10), analysis (texto), recommendations (array), red_flags (array), suggested_specialty (texto), requires_immediate_attention (boolean)`
    },
    {
      role: "user",
      content: patientContext
    }
  ],
  temperature: 0.7,
  max_tokens: 2000
};

return {
  symptoms: symptoms,
  patientInfo: patientInfo,
  additionalNotes: additionalNotes,
  patientContext: patientContext,
  groqBody: groqBody,
  timestamp: new Date().toISOString()
};

// Preservar dados originais - acesso correto ao nó anterior
const groqResponse = $input.item.json;
const prepareData = $('Prepare Data').item.json;

return {
  ...groqResponse,
  _original_patient_data: {
    symptoms: prepareData.symptoms || [],
    patientInfo: prepareData.patientInfo || {}
  }
};

// Processar resposta da IA (GROQ) e estruturar dados finais
const groqResponse = $input.item.json;
const aiResponse = groqResponse.choices?.[0]?.message?.content || groqResponse.message?.content || groqResponse.text || '';

// Recuperar dados originais preservados
const originalPatientData = groqResponse._original_patient_data || {};

let parsedAnalysis;
try {
  // Tentar extrair JSON da resposta
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsedAnalysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (error) {
  // Fallback: estrutura padrão com análise
  parsedAnalysis = {
    classification: "PRIORITÁRIO",
    severity_score: 5,
    analysis: aiResponse || "Não foi possível processar a resposta. Por favor, busque atendimento médico.",
    recommendations: ["Consultar um médico para avaliação completa"],
    red_flags: [],
    suggested_specialty: "Clínico Geral",
    requires_immediate_attention: false
  };
}

// Montar resposta final com dados originais
const response = {
  success: true,
  timestamp: new Date().toISOString(),
  patient_data: {
    symptoms: originalPatientData.symptoms || [],
    patient_info: originalPatientData.patientInfo || {}
  },
  triage_result: parsedAnalysis,
  metadata: {
    processed_at: new Date().toISOString(),
    workflow_version: "1.0.1",
    model: "GROQ - Llama 3.3 70B"
  }
};

return response;

// Tratamento de erro
const error = $input.item.json.error || $input.item.json;

return {
  success: false,
  error: {
    message: "Erro ao processar triagem médica",
    details: error.message || String(error),
    timestamp: new Date().toISOString()
  },
  triage_result: {
    classification: "PRIORITÁRIO",
    severity_score: 5,
    analysis: "Não foi possível processar a análise. Por favor, busque atendimento médico presencial.",
    recommendations: ["Consultar um médico presencialmente"],
    red_flags: ["Sistema de triagem temporariamente indisponível"],
    suggested_specialty: "Clínico Geral",
    requires_immediate_attention: false
  }
};
